    58	 * Roll up one series over the trailing `spanMs` ending at `now`.
    59	 */
    60	export function rollup(
    61	  store: MemoryStore,
    62	  series: string,
    63	  windowMs: number,
    64	  now: number,
    65	  spanMs: number,
