    10	export class MemoryStore {
    11	  private readonly buckets = new Map<string, Sample[]>();
    12	  private readonly maxPerSeries: number;
    13	
    14	  constructor(maxPerSeries: number) {
    15	    if (!Number.isInteger(maxPerSeries) || maxPerSeries <= 0) {
    16	      throw new RangeError("maxPerSeries must be a positive integer");
    17	    }
    18	    this.maxPerSeries = maxPerSeries;
    19	  }
    20	
    21	  /** Insert a sample, keeping the series bucket ordered by timestamp. */
    22	  put(sample: Sample): void {
    23	    let bucket = this.buckets.get(sample.series);
    24	    if (bucket === undefined) {
    25	      bucket = [];
    26	      this.buckets.set(sample.series, bucket);
    27	    }
    28	    const at = insertionPoint(bucket, sample.at);
    29	    bucket.splice(at, 0, sample);
    30	    if (bucket.length > this.maxPerSeries) {
    31	      bucket.splice(0, bucket.length - this.maxPerSeries);
    32	    }
    33	  }
    34	
    35	  /** Samples for `series` with `from <= at < to`, in timestamp order. */
    36	  range(series: string, from: number, to: number): Sample[] {
    37	    const bucket = this.buckets.get(series);
    38	    if (bucket === undefined) return [];
    39	    return bucket.filter((s) => s.at >= from && s.at < to);
    40	  }
    41	
    42	  /** Every series name currently holding at least one sample. */
    43	  series(): string[] {
    44	    return [...this.buckets.keys()].sort();
    45	  }
