    47	  /** Drop every sample older than `before`; returns how many were removed. */
    48	  prune(before: number): number {
    49	    let removed = 0;
    50	    for (const [name, bucket] of this.buckets) {
    51	      const keep = bucket.filter((s) => s.at >= before);
    52	      removed += bucket.length - keep.length;
    53	      if (keep.length === 0) {
    54	        this.buckets.delete(name);
    55	      } else {
