    38	 */
    39	export function validateSample(input: unknown): Sample {
    40	  if (input === null || typeof input !== "object") {
    41	    throw new ValidationError("sample", "expected an object");
    42	  }
    43	  const candidate = input as Record<string, unknown>;
    44	
    45	  if (!isValidSeries(candidate.series)) {
    46	    throw new ValidationError(
    47	      "series",
    48	      "expected a lowercase name matching [a-z][a-z0-9_.-]*",
    49	    );
    50	  }
    51	  if (!isFiniteNumber(candidate.value)) {
    52	    throw new ValidationError("value", "expected a finite number");
    53	  }
    54	  if (!isFiniteNumber(candidate.at) || !Number.isInteger(candidate.at)) {
    55	    throw new ValidationError("at", "expected epoch milliseconds as an integer");
    56	  }
    57	  if (candidate.at < 0) {
